X['ecosize-cxw-111'] = dict(
 how=['Sizing puts a thin, flexible coating on each warp end so it survives the rubbing of heald eyes, drop wires and reed dents. The coating must stick to the fibre, bend without cracking and leave the yarn surface smooth enough that loose fibres lie flat instead of tangling with neighbouring ends.',
      'EcoSize-CXW-111 delivers that coating from one cooked powder. Because the components a mill would normally weigh separately are already balanced inside the product, every batch in the size kitchen starts from the same recipe, and the size box behaves the same way on the morning shift as on the night shift.'],
 bens=[('Lower total sizing cost','Buying, storing and weighing one product instead of PVA, starch, wax and additives cuts purchasing effort, warehouse space and size-kitchen labour. The owner comparison sheet below shows the dosing and savings Seamens records against a common PVA recipe.'),
       ('Fewer warp breaks on the loom','A well-bonded, flexible film resists abrasion, so ends break less often. Fewer breaks mean fewer stoppages, higher loom efficiency and less knotting work for weavers on every shift.'),
       ('Consistent size from batch to batch','A pre-balanced powder removes the weighing errors that come with multi-ingredient recipes. Consistent add-on gives predictable weaving and fewer shade problems after desizing and dyeing.'),
       ('Good adhesion on blends','The size adheres well on polyester-cotton and polyester-viscose yarns as well as cotton, so one product can cover more of the mill\'s constructions.'),
       ('Low foam in the size box','Low foaming keeps the size level stable and the pick-up even across the warp sheet, which protects quality on wide beams.'),
       ('Simpler stock control','One code in the store instead of five or six makes reordering, FIFO rotation and audits straightforward for the stores and purchase teams.')],
 probs=[('Frequent warp breaks','Weak or brittle size film','A flexible, well-bonded film reduces abrasion damage'),('High hairiness after sizing','Size not laying fibres down','Smooth film coats and binds protruding fibres'),('Uneven add-on across shifts','Weighing errors in multi-ingredient recipes','One pre-balanced powder gives a repeatable mix'),('Foam spilling from the size box','Foaming components in the recipe','Low-foam behaviour keeps the box level stable')],
 checks=[('Yarn strength after sizing','Single-end breaking force and elongation on sized and unsized yarn','iso2062'),('Size add-on','Weigh sized and desized yarn samples to confirm the target pick-up','iso2062'),('Loom performance','Track warp breaks per 100,000 picks before and after the trial','iso9001')],
 faq2=[('Is EcoSize-CXW-111 suitable for polyester blends?','Yes. It is used on PC 80/20 and PV 65/35 type blends as well as 100% cotton, with doses confirmed by trial.'),('How quickly can a mill switch to EcoSize-CXW-111?','Most mills run a trial beam first. Once loom results are confirmed, the recipe is switched for that construction and extended to others.'),('Does EcoSize-CXW-111 affect desizing?','The size is designed to come off in normal desizing. Desizing results are checked during the trial so preparation is not affected.')],
 refs=['iso2062','iso13934','iso9001'])

