 probs=[('Streaky reactive shades','Dye striking too fast','Levelling slows and evens uptake'),('Specks on polyester','Disperse dye agglomeration','Dispersing keeps particles separated'),('Lot-to-lot shade variation','Uncontrolled exhaustion','Controlled, repeatable uptake'),('Frequent re-dyeing','Unlevel first dye','Higher right-first-time rate')],
 checks=[('Shade levelness','Visual and spectrophotometer assessment across the batch against the standard','iso9001'),('Wash fastness','Colour change and staining after laundering','iso105c06'),('Rubbing fastness','Dry and wet rubbing on the dyed fabric','iso105x12')],
